package ru.truetv.launcher;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.graphics.*;import android.view.*;import android.view.accessibility.AccessibilityEvent;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Disposable VM: no help rows, actual radio events, split Wi-Fi ink and non-mutating long OK. */
public final class HeaderRadioCheck extends Instrumentation {
 private HomeActivity home;private Context c;private int checks;private final StringBuilder log=new StringBuilder();private Map<String,?> before;private boolean wifiBefore;
 public void onCreate(Bundle b){super.onCreate(b);start();}private void check(boolean ok,String text){checks++;log.append(ok?"PASS ":"FAIL ").append(text).append('\n');if(!ok)throw new AssertionError(text);}private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}interface Condition{boolean ok()throws Exception;}private void until(Condition condition)throws Exception{long end=SystemClock.uptimeMillis()+30000;while(!condition.ok()&&SystemClock.uptimeMillis()<end){VmWindows.clear(this);Thread.sleep(100);}check(condition.ok(),"await condition");}private Glyph icon(int n){return (Glyph)((FrameLayout)home.header.getChildAt(n)).getChildAt(0);}private int alpha(boolean dot){final int[] value={0};main(()->{Bitmap bitmap=Bitmap.createBitmap(icon(5).getWidth(),icon(5).getHeight(),Bitmap.Config.ARGB_8888);icon(5).draw(new Canvas(bitmap));float scale=bitmap.getWidth()/24f;value[0]=Color.alpha(bitmap.getPixel(Math.round(12*scale),(int)((dot?17:4)*scale)));bitmap.recycle();});return value[0];}private void shell(String text)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(text))){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}private void screenshot(String name)throws Exception{Thread.sleep(250);Bitmap bitmap=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),"header-"+BuildConfig.VERSION_CODE+"-"+name+"-api"+Build.VERSION.SDK_INT+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
 public void onStart(){Bundle result=new Bundle();try{c=getTargetContext();check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"VM guard");SettingsStore prefs=new SettingsStore(c);before=new HashMap<>(prefs.data.getAll());prefs.data.edit().putBoolean("bt_count",false).putBoolean("bt_asked",true).putBoolean("running",false).putString("theme","black").commit();wifiBefore=RadioControls.wifiState(c)==RadioControls.ON;VmWindows.prepare(this);home=VmWindows.home(this);until(()->home.hasWindowFocus());LinearLayout root=(LinearLayout)home.header.getParent();check(root.getChildCount()==3&&root.getChildAt(1)==home.board,"desktop contains header, board and version only; both help rows and their reserve are removed");check(home.board.getTop()==home.header.getBottom(),"desktop starts immediately below header");check(icon(5).getWidth()==Ui.dp(c,36),"top glyph size remains36dp");check(home.header.getChildAt(5).isLongClickable()&&home.header.getChildAt(6).isLongClickable(),"both radio buttons retain long OK");Set<String> permissions=new HashSet<>(Arrays.asList(c.getPackageManager().getPackageInfo(c.getPackageName(),PackageManager.GET_PERMISSIONS).requestedPermissions));check(!permissions.contains("android.permission.ACCESS_FINE_LOCATION")&&!permissions.contains("android.permission.ACCESS_COARSE_LOCATION"),"removed network-name UI no longer requests Location permissions");check(!permissions.contains("android.permission.CHANGE_WIFI_STATE")&&!permissions.contains("android.permission.BLUETOOTH_ADMIN"),"launcher no longer requests obsolete radio-toggle permissions");
 shell("svc wifi disable");until(()->RadioControls.wifiState(c)==RadioControls.OFF);until(()->alpha(true)<128&&alpha(false)<128);check(home.header.getChildAt(5).getAlpha()==1f,"only icon ink dims; focus target remains visible");Board board=home.board;int btBefore=RadioControls.bluetoothState(c);final ArrayList<Intent> launches=new ArrayList<>();ActivityMonitor monitor=new ActivityMonitor(){public ActivityResult onStartActivity(Intent intent){launches.add(new Intent(intent));return new ActivityResult(Activity.RESULT_CANCELED,null);}};addMonitor(monitor);
 main(()->home.header.getChildAt(6).performLongClick());Field noticeField=HomeActivity.class.getDeclaredField("headerNotice");noticeField.setAccessible(true);PopupWindow btNotice=(PopupWindow)noticeField.get(home);check(btNotice!=null&&btNotice.isShowing()&&((TextView)btNotice.getContentView()).getText().toString().contains("Bluetooth"),"Bluetooth long OK shows its header notice");int[] headPosition=new int[2],noticePosition=new int[2];home.header.getLocationOnScreen(headPosition);btNotice.getContentView().getLocationOnScreen(noticePosition);check(noticePosition[1]>=headPosition[1]+home.header.getHeight()&&noticePosition[1]<=headPosition[1]+home.header.getHeight()+Ui.dp(c,8),"long-press notice appears directly below system icons, not at screen bottom");check(!btNotice.isFocusable()&&!btNotice.isTouchable(),"notice does not take remote focus or intercept clicks");main(()->home.header.getChildAt(5).requestFocusFromTouch());sendKeySync(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER));Thread.sleep(ViewConfiguration.getLongPressTimeout()+300);sendKeySync(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_CENTER));waitForIdleSync();PopupWindow wifiNotice=(PopupWindow)noticeField.get(home);check(wifiNotice!=null&&wifiNotice.isShowing()&&((TextView)wifiNotice.getContentView()).getText().toString().contains("Wi-Fi"),"actual held remote OK shows Wi-Fi notice below header");check(launches.isEmpty()&&home.hasWindowFocus(),"long OK opens no settings, chooser, enable dialog or other Activity");check(RadioControls.wifiState(c)==RadioControls.OFF&&RadioControls.bluetoothState(c)==btBefore,"long OK changes neither radio state");screenshot("hint-under-icons");removeMonitor(monitor);
 Field field=HomeActivity.class.getDeclaredField("status");field.setAccessible(true);StatusWatch watch=(StatusWatch)field.get(home);main(watch::stop);main(()->home.radios(RadioControls.ON,RadioControls.OFF,0));check(alpha(true)>230&&alpha(false)<128,"enabled unassociated Wi-Fi has a bright dot and dim waves");check(icon(6).getAlpha()<.5f,"Bluetooth OFF is dim");screenshot("wifi-no-network");main(()->home.radios(RadioControls.ON,RadioControls.ON,1));check(alpha(true)>230&&alpha(false)>230,"associated Wi-Fi has bright dot and waves");check(icon(6).getAlpha()==1f,"Bluetooth ON is bright");main(()->home.radios(RadioControls.OFF,RadioControls.OFF,0));check(alpha(true)<128&&alpha(false)<128,"Wi-Fi OFF dims the whole glyph");main(()->home.radios(RadioControls.UNKNOWN,RadioControls.UNKNOWN,RadioControls.UNKNOWN));check(alpha(true)>230&&alpha(false)>230,"unknown state is not falsely rendered as OFF or disconnected");check(home.board==board&&root.getChildCount()==3,"radio updates preserve the same desktop without adding captions");check(home.header.getChildAt(7).getNextFocusRightId()==home.header.getChildAt(0).getId(),"all eight header controls retain cyclic focus");
 shell("svc wifi enable");until(()->RadioControls.wifiState(c)==RadioControls.ON);main(watch::start);until(()->alpha(true)>230);int connection=RadioControls.wifiConnection(c);if(connection>=0){until(()->RadioControls.wifiConnection(c)==0?alpha(false)<128:alpha(false)>230);check(connection==0||connection==1,"current physical Wi-Fi association is available without Location access");}screenshot("radio-states");log.append("LIMIT no Bluetooth adapter required: BT colors injected; physical/OEM Bluetooth state still requires device check\n");result.putBoolean("passed",true);
 }catch(Throwable t){StringWriter s=new StringWriter();t.printStackTrace(new PrintWriter(s));log.append(s);result.putBoolean("passed",false);}finally{try{shell("svc wifi "+(wifiBefore?"enable":"disable"));if(home!=null)main(home::finish);if(before!=null){SharedPreferences.Editor e=new SettingsStore(c).data.edit().clear();for(Map.Entry<String,?> x:before.entrySet()){Object v=x.getValue();if(v instanceof String)e.putString(x.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(x.getKey(),(Boolean)v);else if(v instanceof Integer)e.putInt(x.getKey(),(Integer)v);else if(v instanceof Long)e.putLong(x.getKey(),(Long)v);}e.commit();}}catch(Exception e){log.append("RESTORE ").append(e);}}result.putString("report",log+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
